"use client"

import { useState, useEffect, useRef, type UIEvent } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Label } from "@/components/ui/label"
import { Search, X, Pill, Filter } from "lucide-react"
import { useProductSearch } from "@/hooks/products"
import { formatRWF } from "@/lib/utils"
import { getInsuranceAwarePricing } from "@/lib/insurance-utils"

type ProductTypeFilter = 'ALL' | 'DRUG' | 'MEDICAL_ACT' | 'BIOLOGICAL_ACT' | 'CONSUMABLE_DEVICE'

interface InsuranceCoverage {
  id: string
  insuranceProvider: {
    id: string
    insuranceName: string
    acronym?: string | null
    coverages: { patientSharePercentage: number }[]
  }
  cost: number
  covered: boolean
}

interface PatientInsurance {
  id: string
  insuranceProvider: {
    id: string
    insuranceName: string
    acronym?: string | null
    coverages: { patientSharePercentage: number }[]
  }
}

interface ActionOrConsumable {
  id: string
  name: string
  privatePrice: number
  isQuantifiable?: boolean
  type?: ProductTypeFilter
  description?: string
  insuranceCoverages?: InsuranceCoverage[]
  clinicPrice?: number | null
  privateRhicPrice?: number | null
}

interface Processor {
  id: string
  firstName: string
  lastName?: string | null
}

interface AddActionConsumableModalProps {
  isOpen: boolean
  onClose: () => void
  departments: { id: string; name: string; visitDepartmentId?: string }[]
  currentDepartmentId?: string
  visitDepartmentId?: string
  viewMode: 'all' | 'service'
  onAdd: (type: 'action' | 'consumable', item: ActionOrConsumable, quantity: number, departmentId: string, processorId?: string) => void
  existingProductReferenceIds?: string[]
  isSubmitting?: boolean
  linkedInsurances?: PatientInsurance[]
  /** Workers assigned as processors for the active visit department. */
  processors?: Processor[]
}

export default function AddActionConsumableModal({
  isOpen,
  onClose,
  departments,
  currentDepartmentId,
  visitDepartmentId,
  viewMode,
  onAdd,
  existingProductReferenceIds = [],
  isSubmitting = false,
  linkedInsurances = [],
  processors = [],
}: AddActionConsumableModalProps) {
  const filterOptions: ProductTypeFilter[] = ['ALL', 'DRUG', 'MEDICAL_ACT', 'BIOLOGICAL_ACT', 'CONSUMABLE_DEVICE']
  const [productType, setProductType] = useState<ProductTypeFilter>('ALL')
  const [showFilterOptions, setShowFilterOptions] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState('')
  const [suggestions, setSuggestions] = useState<ActionOrConsumable[]>([])
  const [loadingMore, setLoadingMore] = useState(false)
  const [hoveredItemId, setHoveredItemId] = useState<string | null>(null)
  const [selectedItem, setSelectedItem] = useState<ActionOrConsumable | null>(null)
  const [quantity, setQuantity] = useState('1')
  const [selectedDepartmentId, setSelectedDepartmentId] = useState(currentDepartmentId || '')
  const [selectedProcessorId, setSelectedProcessorId] = useState<string>('')
  const isFetchingMoreRef = useRef(false)
  const existingProductIdSet = new Set((existingProductReferenceIds || []).map(String))
  const selectedAlreadyAdded = selectedItem ? existingProductIdSet.has(selectedItem.id) : false

  // Resolve active visit department id for backend product filtering
  const activeVisitDepartmentId = departments.find((d) => d.id === selectedDepartmentId)?.visitDepartmentId || visitDepartmentId

  // Helper to get insurance-aware pricing
  const resolveItemPricing = (item: ActionOrConsumable) => {
    return getInsuranceAwarePricing(item, linkedInsurances)
  }
  const {
    products: searchedProducts,
    loading,
    hasMore,
    loadMore,
  } = useProductSearch(debouncedSearchQuery, {
    type: productType,
    size: 10,
    visitDepartmentId: activeVisitDepartmentId,
  })

  // Keep department selection in sync with the view's current department
  useEffect(() => {
    if (currentDepartmentId && currentDepartmentId !== selectedDepartmentId) {
      setSelectedDepartmentId(currentDepartmentId)
    }
  }, [currentDepartmentId, selectedDepartmentId])

  // Auto-select processor when there's exactly one, clear selection when processors change
  useEffect(() => {
    if (processors.length === 1) {
      setSelectedProcessorId(processors[0].id)
    } else if (processors.length === 0) {
      setSelectedProcessorId('')
    } else {
      setSelectedProcessorId('')
    }
  }, [processors])

  // Debounce the search input before querying the shared products hook.
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery.trim().length >= 2 ? searchQuery.trim() : '')
    }, 300)

    return () => clearTimeout(timer)
  }, [searchQuery])

  useEffect(() => {
    if (!debouncedSearchQuery) {
      setSuggestions((prev) => (prev && prev.length ? [] : prev))
      return
    }

    const results = (searchedProducts || [])
      .map((item: any) => ({
        id: String(item.id),
        name: item.name,
        privatePrice: Number(item.privateRhicPrice ?? item.clinicPrice ?? 0),
        isQuantifiable: item.quantifiable !== false,
        type: item.type,
        description: item.description,
        ...item,
      }))

    // Only update suggestions if results changed (avoid repeated identical setState)
    setSuggestions((prev) => {
      const prevIds = (prev || []).map((p) => p.id).join(',')
      const nextIds = (results || []).map((r: { id: string }) => r.id).join(',')
      if (prevIds === nextIds) return prev
      return results
    })
  }, [debouncedSearchQuery, searchedProducts, productType])

  const handleSelectItem = (item: ActionOrConsumable) => {
    setSelectedItem(item)
  }

  const handleAddItem = () => {
    if (!selectedItem || !selectedDepartmentId) return

    const qty = selectedItem.isQuantifiable === false ? 1 : (parseInt(quantity, 10) || 1)
    const itemType = selectedItem.type === 'CONSUMABLE_DEVICE' ? 'consumable' : 'action'
    const processorId = selectedProcessorId || undefined
    onAdd(itemType, selectedItem, qty, selectedDepartmentId, processorId)

    // Reset form
    setSelectedItem(null)
    setQuantity('1')
    setSearchQuery('')
    setSuggestions([])
    setSelectedProcessorId(processors.length === 1 ? processors[0].id : '')
    onClose()
  }

  const handleClose = () => {
    setSelectedItem(null)
    setQuantity('1')
    setSearchQuery('')
    setSuggestions([])
    setShowFilterOptions(false)
    setSelectedProcessorId(processors.length === 1 ? processors[0].id : '')
    onClose()
  }

  const handleSuggestionsScroll = async (e: UIEvent<HTMLDivElement>) => {
    const element = e.currentTarget
    const nearBottom = element.scrollTop + element.clientHeight >= element.scrollHeight - 24

    if (!nearBottom) return
    if (!hasMore) return
    if (loading || loadingMore || isFetchingMoreRef.current) return

    try {
      isFetchingMoreRef.current = true
      setLoadingMore(true)
      await loadMore()
    } finally {
      setLoadingMore(false)
      isFetchingMoreRef.current = false
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => {
      if (!open) handleClose()
    }}>
      <DialogContent showCloseButton={false} className="sm:max-w-[600px] backdrop-blur-2xl bg-card/95 dark:bg-card/95 text-card-foreground rounded-3xl border border-border/80 shadow-2xl">
        <DialogHeader className="text-center space-y-2">
          <DialogTitle className="text-center">Add Product</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Spotlight-style Search Box - Hidden when item selected */}
          {!selectedItem && (
          <div className="relative bg-white dark:bg-gray-900 rounded-2xl border border-border shadow-md overflow-hidden">
            {/* Search Input */}
            <div className="px-4 py-3 flex items-center gap-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <Input
                  type="text"
                  placeholder="Search..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onFocus={() => setShowFilterOptions(false)}
                  className="pl-10 pr-10 h-12 text-base bg-transparent border border-gray-300 dark:border-gray-700 rounded-lg focus-visible:ring-0 focus-visible:ring-offset-0"
                />
                {searchQuery && (
                  <button
                    type="button"
                    onClick={() => setSearchQuery('')}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                  >
                    <X className="w-5 h-5" />
                  </button>
                )}
              </div>

              <Button
                type="button"
                variant={productType === 'ALL' ? 'outline' : 'default'}
                size="icon"
                className="h-12 w-12"
                onClick={() => setShowFilterOptions((prev) => !prev)}
                aria-label="Toggle filters"
              >
                <Filter className="h-4 w-4" />
              </Button>
            </div>

            {(showFilterOptions || productType !== 'ALL') && (
              <div className="px-4 pb-3 space-y-2 border-t border-border/30">
                {showFilterOptions && (
                  <div className="flex flex-wrap gap-2 pt-2">
                    {filterOptions.map((option) => (
                      <Button
                        key={option}
                        type="button"
                        size="sm"
                        variant={productType === option ? 'default' : 'outline'}
                        className="h-7 px-2 text-xs"
                        onClick={() => {
                          setProductType(option)
                          if (option !== 'ALL') {
                            setShowFilterOptions(false)
                          }
                        }}
                      >
                        {option}
                      </Button>
                    ))}
                  </div>
                )}

                {productType !== 'ALL' && (
                  <div className="pt-1">
                    <button
                      type="button"
                      onClick={() => setProductType('ALL')}
                      className="inline-flex items-center gap-1 rounded-full border border-primary/40 bg-primary/10 px-2 py-1 text-xs text-primary hover:bg-primary/20"
                    >
                      <Filter className="h-3 w-3" />
                      {productType}
                      <X className="h-3 w-3" />
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
          )}

          {/* Results Container - Separate card */}
          {!selectedItem && (loading || suggestions.length > 0) && (
            <div className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm rounded-2xl border border-border shadow-sm p-4 min-h-[100px]">
              {/* Loading indicator */}
              {loading && (
                <div className="flex items-center justify-center gap-0.5 text-sm text-muted-foreground">
                  <span className="flex gap-1">
                    <span className="w-2 h-2 rounded-full bg-primary animate-bounce" style={{ animationDelay: "0ms" }}></span>
                    <span className="w-2 h-2 rounded-full bg-primary animate-bounce" style={{ animationDelay: "150ms" }}></span>
                    <span className="w-2 h-2 rounded-full bg-primary animate-bounce" style={{ animationDelay: "300ms" }}></span>
                    <span className="w-2 h-2 rounded-full bg-primary animate-bounce" style={{ animationDelay: "450ms" }}></span>
                  </span>
                </div>
              )}

              {/* Results List */}
              {!loading && suggestions.length > 0 && (
                <div className="space-y-2 max-h-[320px] overflow-y-auto pr-1" onScroll={handleSuggestionsScroll}>
                  {suggestions.map((item) => {
                    const alreadyAdded = existingProductIdSet.has(item.id)
                    return (
                      <div
                        key={item.id}
                        onClick={() => handleSelectItem(item)}
                        onMouseEnter={() => setHoveredItemId(item.id)}
                        onMouseLeave={() => setHoveredItemId((prev) => (prev === item.id ? null : prev))}
                        className={
                          `p-4 rounded-xl border-2 cursor-pointer transition-all duration-300 bg-background border-border/40 hover:border-primary/50 hover:shadow-sm hover:scale-[1.01] ${
                            alreadyAdded ? 'opacity-90 border-amber-300 bg-amber-50/50' : ''
                          }`
                        }
                      >
                        <div className="flex items-center justify-between gap-2">
                          <div className="flex-1">
                            <div className="font-medium">{item.name}</div>
                            {(() => {
                              const pricing = resolveItemPricing(item)
                              return (
                                <div className="text-sm mt-1 space-y-1">
                                  {pricing.coverageDetails.length > 0 ? (
                                    pricing.coverageDetails.map((coverage, idx) => {
                                      const isZeroPaying = Number(coverage.cost) <= 0 || coverage.covered === false
                                      return (
                                        <div key={idx} className="flex items-center gap-2">
                                          <span className={`font-semibold ${isZeroPaying ? "text-muted-foreground line-through" : "text-primary"}`}>
                                            {Number(coverage.cost).toLocaleString()} RWF
                                          </span>
                                          <span className="text-xs text-muted-foreground">
                                            {coverage.insuranceProvider.acronym || coverage.insuranceProvider.insuranceName}
                                          </span>
                                          {isZeroPaying && (
                                            <span className="text-[11px] bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 px-1.5 py-0.5 rounded font-medium">
                                              {Number(coverage.cost) === 0 ? "Pays 0 RWF (Not Covered)" : "Not Covered"}
                                            </span>
                                          )}
                                        </div>
                                      )
                                    })
                                  ) : (
                                    <div className="text-muted-foreground flex items-center gap-2">
                                      <span>{formatRWF(pricing.price)}</span>
                                      {linkedInsurances.length > 0 && (
                                        <span className="text-[11px] bg-amber-100 dark:bg-amber-900/30 text-amber-800 dark:text-amber-300 px-1.5 py-0.5 rounded font-medium">
                                          Private (No Insurance Coverage)
                                        </span>
                                      )}
                                    </div>
                                  )}
                                </div>
                              )
                            })()}
                            {hoveredItemId === item.id && (
                              <div className="mt-2 rounded-md border border-border/50 bg-muted/30 p-2 text-xs text-muted-foreground">
                                {item.description?.trim() || 'No description available'}
                              </div>
                            )}
                          </div>
                          {alreadyAdded && (
                            <span className="rounded-full bg-amber-100 text-amber-800 px-2 py-1 text-[12px] font-semibold uppercase tracking-[0.08em]">
                              Already added
                            </span>
                          )}
                        </div>
                      </div>
                    )
                  })}
                  {loadingMore && <div className="text-center text-xs text-muted-foreground py-1">Loading more...</div>}
                  {!loadingMore && hasMore && <div className="text-center text-xs text-muted-foreground py-1">Scroll to load more</div>}
                </div>
              )}
            </div>
          )}

          {/* Configuration Section - Only when item selected */}
          {selectedItem && (
            <div className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm rounded-2xl border border-border shadow-sm p-4 space-y-4">
              {/* Selected Item Summary */}
              <div className="bg-primary/5 border border-primary/20 rounded-xl p-3 space-y-3">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <Pill className="w-4 h-4 text-primary" />
                    <span className="text-sm font-medium">Selected Product</span>
                  </div>
                  <div className="flex items-center gap-2 mb-2">
                    <div className="text-sm text-muted-foreground">{selectedItem.name}</div>
                    {processors.length > 1 && selectedProcessorId && (() => {
                      const proc = processors.find(p => p.id === selectedProcessorId)
                      if (!proc) return null
                      return (
                        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-emerald-700 dark:text-emerald-300 bg-emerald-50 dark:bg-emerald-900/30 border border-emerald-200 dark:border-emerald-800 px-1.5 py-0.5 rounded-full">
                          <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                          {proc.firstName} {proc.lastName || ''}
                        </span>
                      )
                    })()}</div>
                  
                  {(() => {
                    const pricing = resolveItemPricing(selectedItem)
                    return (
                      <div className="space-y-1.5">
                        {pricing.coverageDetails.length > 0 ? (
                          pricing.coverageDetails.map((coverage, idx) => {
                            const isZeroPaying = Number(coverage.cost) <= 0 || coverage.covered === false
                            return (
                              <div key={idx} className="flex justify-between text-xs">
                                <div className="flex items-center gap-2">
                                  <span className="text-muted-foreground">
                                    Unit Price ({coverage.insuranceProvider.acronym || coverage.insuranceProvider.insuranceName}):
                                  </span>
                                  {isZeroPaying && (
                                    <span className="text-[11px] bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 px-1.5 py-0.5 rounded font-medium">
                                      {Number(coverage.cost) === 0 ? "Pays 0 RWF (Not Covered)" : "Not Covered"}
                                    </span>
                                  )}
                                </div>
                                <span className={`font-semibold ${isZeroPaying ? "text-muted-foreground line-through" : "text-foreground"}`}>
                                  {Number(coverage.cost).toLocaleString()} RWF
                                </span>
                              </div>
                            )
                          })
                        ) : (
                          <div className="flex justify-between text-xs">
                            <div className="flex items-center gap-2">
                              <span className="text-muted-foreground">Private Price:</span>
                              {linkedInsurances.length > 0 && (
                                <span className="text-[11px] bg-amber-100 dark:bg-amber-900/30 text-amber-800 dark:text-amber-300 px-1.5 py-0.5 rounded font-medium">
                                  Not Covered by Insurance
                                </span>
                              )}
                            </div>
                            <span className="font-semibold">{formatRWF(pricing.price)}</span>
                          </div>
                        )}
                        {pricing.allCoveragesZeroOrNotCovered && (
                          <div className="mt-2 rounded-lg border border-amber-300 dark:border-amber-700 bg-amber-50 dark:bg-amber-950/30 p-2 text-xs text-amber-900 dark:text-amber-200">
                            ⚠️ This product pays 0 RWF / is not covered by the patient&apos;s insurance. It will bill under Private pricing ({formatRWF(Number(selectedItem.clinicPrice ?? selectedItem.privateRhicPrice ?? 0))}).
                          </div>
                        )}
                      </div>
                    )
                  })()}
                </div>
                {selectedAlreadyAdded && (
                  <div className="rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-900">
                    This product is already added to the consultation. Adding it again will update the quantity.
                  </div>
                )}
              </div>

              {/* Quantity Input (if quantifiable) */}
              {selectedItem.isQuantifiable !== false && (
                <div className="space-y-2">
                  <Label className="text-sm font-medium">Quantity</Label>
                  <Input
                    type="number"
                    min="1"
                    value={quantity}
                    onChange={(e) => setQuantity(e.target.value)}
                    placeholder="Enter quantity"
                    className="h-10"
                  />
                  {(() => {
                    const pricing = resolveItemPricing(selectedItem)
                    const qtyNum = parseInt(quantity, 10) || 1
                    return (
                      <div className="flex justify-between text-xs text-muted-foreground">
                        <span>Total:</span>
                        <span className="font-semibold text-foreground">
                          {formatRWF(pricing.price * qtyNum)}
                        </span>
                      </div>
                    )
                  })()}
                </div>
              )}

              {/* Processor Selection — only show when 2+ processors; single processor is silently auto-assigned */}
              {processors.length > 1 && (
                <div className="space-y-2">
                  <Label className="text-sm font-medium">Processor</Label>
                  <Select
                    value={selectedProcessorId}
                    onValueChange={setSelectedProcessorId}
                  >
                    <SelectTrigger className="h-10">
                      <SelectValue placeholder="Choose processor..." />
                    </SelectTrigger>
                    <SelectContent>
                      {processors.map((proc) => (
                        <SelectItem key={proc.id} value={proc.id}>
                          {proc.firstName} {proc.lastName || ''}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}

              {/* Department Selection (all-items view) */}
              {(viewMode === 'all' || !currentDepartmentId) && (
                <div className="space-y-2">
                  <Label className="text-sm font-medium">Target Department</Label>
                  <Select
                    value={selectedDepartmentId}
                    onValueChange={setSelectedDepartmentId}
                    disabled={Boolean(currentDepartmentId)}
                  >
                    <SelectTrigger className="h-10">
                      <SelectValue placeholder="Choose department..." />
                    </SelectTrigger>
                    <SelectContent>
                      {departments.map((dept) => (
                        <SelectItem key={dept.id} value={dept.id}>
                          {dept.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}
            </div>
          )}
        </div>

        {selectedItem && (
        <DialogFooter className="gap-2 mt-4 justify-center">
          <Button variant="outline" onClick={handleClose} className="rounded-full">
            Cancel
          </Button>              <Button
                onClick={handleAddItem}
                disabled={!selectedItem || !selectedDepartmentId || loading || isSubmitting}
                className="bg-primary hover:bg-primary/90 text-primary-foreground rounded-full"
              >
                Add Product
              </Button>
        </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  )
}
